WITH with_windows AS (SELECT id, session_id, event_type, page, MAX(duration_sec) OVER (PARTITION BY session_id, event_type ORDER BY event_time, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_duration_sec, AVG(duration_sec) OVER (PARTITION BY session_id, event_type ORDER BY event_time, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_duration_sec, COUNT(duration_sec) OVER (PARTITION BY session_id, event_type ORDER BY event_time, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_duration_sec, MIN(duration_sec) OVER (PARTITION BY session_id, event_type ORDER BY event_time, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_duration_sec, SUM(duration_sec) OVER (PARTITION BY page, event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec FROM web_events) SELECT id, event_type, page, last4_max_duration_sec, last4_count_duration_sec, last4_min_duration_sec FROM with_windows ORDER BY last4_count_duration_sec DESC
